import type * as React from "react"

import { Logo } from "@/components/ui/logo"
import { SemanticContent } from "@/components/ui/semantic-content"

/** The brand mark alone, centered, with an optional caption. */
export default function LogoMark({ name = "Clossys", mark, caption }: { name?: string; mark?: React.ReactNode; caption?: string }) {
  return (
    <section data-slot="logo-mark" className="py-12">
      <SemanticContent as="figure" className="mx-auto flex max-w-5xl flex-col items-center gap-4 px-6">
        <Logo content="mark" size="lg" name={name} mark={mark} />
        {caption && <SemanticContent as="figcaption">{caption}</SemanticContent>}
      </SemanticContent>
    </section>
  )
}
